import json
import boto3
from typing import Dict, Any

def normalize_expense_fields(extracted_text: str) -> Dict[str, Any]:
    """
    Normalizes extracted expense fields into a standard JSON schema using AWS Textract.

    Args:
        extracted_text: Raw text extracted from an expense document (e.g., receipt or invoice).

    Returns:
        A dictionary conforming to the standard expense schema:
        {
            "vendor": str,
            "date": str (ISO 8601),
            "total_amount": float,
            "currency": str,
            "line_items": [
                {
                    "description": str,
                    "quantity": float,
                    "unit_price": float,
                    "amount": float
                }
            ]
        }
    """
    # Initialize AWS Textract client
    textract = boto3.client('textract', region_name='us-east-1')

    # Prepare the document for Textract (assuming extracted_text is from an image or PDF)
    # In practice, you would upload the document to S3 and use its URI here
    # For this example, we simulate a document with the extracted text
    document = {
        'Bytes': extracted_text.encode('utf-8') if isinstance(extracted_text, str) else extracted_text
    }

    # Call AWS Textract to analyze the expense document
    response = textract.analyze_expense(Document=document)

    # Initialize normalized expense data
    normalized_expense = {
        "vendor": None,
        "date": None,
        "total_amount": None,
        "currency": None,
        "line_items": []
    }

    # Parse Textract response to extract and normalize fields
    for expense_doc in response.get('ExpenseDocuments', []):
        for summary_field in expense_doc.get('SummaryFields', []):
            field_type = summary_field.get('Type', {}).get('Text', '').lower()

            if field_type == 'vendorname':
                normalized_expense["vendor"] = summary_field.get('ValueDetection', {}).get('Text', '')
            elif field_type == 'invoicedate':
                date_text = summary_field.get('ValueDetection', {}).get('Text', '')
                # Normalize date to ISO 8601 format (simplified; use dateutil.parser for robustness)
                normalized_expense["date"] = date_text
            elif field_type == 'total':
                normalized_expense["total_amount"] = float(summary_field.get('ValueDetection', {}).get('Text', '0').replace(',', ''))
            elif field_type == 'currency':
                normalized_expense["currency"] = summary_field.get('ValueDetection', {}).get('Text', '')

        for line_item_group in expense_doc.get('LineItemGroups', []):
            for line_item in line_item_group.get('LineItems', []):
                item = {
                    "description": "",
                    "quantity": 1.0,
                    "unit_price": 0.0,
                    "amount": 0.0
                }
                for line_item_field in line_item.get('LineItemExpenseFields', []):
                    field_type = line_item_field.get('Type', {}).get('Text', '').lower()
                    value_text = line_item_field.get('ValueDetection', {}).get('Text', '')

                    if field_type == 'description':
                        item["description"] = value_text
                    elif field_type == 'quantity':
                        item["quantity"] = float(value_text) if value_text else 1.0
                    elif field_type == 'unitprice':
                        item["unit_price"] = float(value_text.replace(',', '')) if value_text else 0.0
                    elif field_type == 'price':
                        item["amount"] = float(value_text.replace(',', '')) if value_text else 0.0

                # Ensure amount is calculated if not provided
                if item["amount"] == 0.0 and item["quantity"] > 0 and item["unit_price"] > 0:
                    item["amount"] = item["quantity"] * item["unit_price"]

                normalized_expense["line_items"].append(item)

    return normalized_expense
